from PIL import Image
import numpy as np

def rgb565_to_rgb888(rgb565):
    """Convert RGB565 (16-bit) to RGB888 (24-bit)"""
    r = ((rgb565 >> 11) & 0x1F) << 3
    g = ((rgb565 >> 5) & 0x3F) << 2
    b = (rgb565 & 0x1F) << 3
    return (r, g, b)

def parse_hex_image(hex_string, width=48, height=48):
    """Parse hex string into image array"""
    hex_values = hex_string.split()
    image = []
    for hex_val in hex_values:
        rgb565 = int(hex_val, 16)
        image.append(rgb565_to_rgb888(rgb565))
    return np.array(image, dtype=np.uint8).reshape(height, width, 3)

